import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {pathToFileURL} from 'node:url';
import {join} from 'node:path';
const args=process.argv.slice(2),median=a=>[...a].sort((a,b)=>a-b)[Math.floor(a.length/2)];
if(args[0]==='sample'){
 const [,agent,runtimePath,imagePath]=args;
 const {verifyRuntime}=await import(pathToFileURL(join(agent,'tools/agent4/dependencies.mjs')));const runtime=verifyRuntime(runtimePath),world=await import(pathToFileURL(runtime.entrypoint)),image=readFileSync(imagePath);
 const k=await world.Kernel.create({bytes:readFileSync(runtime.kernelPath),expectedSha256:runtime.kernelSha256});k.setLimits({input:256<<20,working:256<<20,output:256<<20});
 const samples=[];for(let batch=0;batch<76;batch++){let ns=0;for(let i=0;i<64;i++){const start=process.hrtime.bigint(),p=k.prepare(image);ns+=Number(process.hrtime.bigint()-start);k.releasePrepared(p);}samples.push(ns/64);assert.equal(k.usage().workingLive,0n);}
 console.log(JSON.stringify({allBatchesNs:samples,firstBatchNs:samples[0],stabilizedSamplesNs:samples.slice(64)}));
}else{
 const [agent,runtime,control,candidate,output]=args,windows=[];
 for(let i=0;i<5;i++){const row={order:i%2?['candidate','control']:['control','candidate']};for(const arm of row.order)row[arm]=JSON.parse(execFileSync(process.execPath,[new URL(import.meta.url).pathname,'sample',agent,runtime,arm==='control'?control:candidate],{encoding:'utf8',timeout:120000}));row.stabilizedRatio=median(row.candidate.stabilizedSamplesNs)/median(row.control.stabilizedSamplesNs);row.firstBatchRatio=row.candidate.firstBatchNs/row.control.firstBatchNs;windows.push(row);}
 const report={scope:'Diagnostic of WASM tiering for the unchanged composed empty-handler input. Original 3-warmup/9-sample timing result remains authoritative and preserved separately. Each process records 76 batches of 64 admissions; stabilized samples follow 64 batches.',windows,stabilizedMedianRatio:median(windows.map(w=>w.stabilizedRatio)),firstBatchMedianRatio:median(windows.map(w=>w.firstBatchRatio))};writeFileSync(output,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({stabilized:report.stabilizedMedianRatio,firstBatch:report.firstBatchMedianRatio}));
}
